"""Tests for committing selfdoc-generated files during release.

Phase 1c: after selfdoc gen/check/post_generate, any newly dirty files
are committed immediately via commit_files(autogenerated=True).  This
ensures the working tree is clean if later steps fail.
"""

import inspect
import json
from unittest.mock import MagicMock, patch, call

import pytest

from conftest import make_ctx
from rlsbl.release_file import ReleaseConfig


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _make_release_context(tmp_path):
    """Build a minimal project context for _run_cmd_inner tests."""
    rlsbl_dir = tmp_path / ".rlsbl"
    rlsbl_dir.mkdir(exist_ok=True)
    (rlsbl_dir / "config.json").write_text(json.dumps({"private": False}))
    return make_ctx(tmp_path, config={"private": False})


def _make_release_config():
    """Create a minimal ReleaseConfig."""
    return ReleaseConfig(bump="patch", include=[], exclude=[], description="test release")


# Standard set of patches needed to reach the selfdoc commit logic in
# _run_cmd_inner's standalone (non-releasable) path.  Every test in this
# module stacks additional patches on top of this base set.
_BASE_PATCHES = {
    "validate_release_targets": "pypi",
    "validate_ota_mode": None,
    "validate_config_integrity": None,
    "validate_pipeline_config": None,
    "validate_gh_cli": None,
    "validate_clean_tree": set(),
    "validate_branch_and_remote": "main",
    "resolve_monorepo_context": (None, None, False, False, None),
    "_abort_on_scaffold_conflicts": None,
    "resolve_target_paths": {},
    "compute_release_version": ("0.1.0", "0.1.1", "patch", "v0.1.1"),
    "validate_changelog_state": None,
    "validate_blog_body": (None, None),
    "extract_changelog_entry_from_text": "- test",
    "build_hook_env": {},
    "get_hook_timeout": 30,
    "_is_hook_effectively_empty": True,
    "_run_builtin_tests": None,
    "_run_builtin_lint": None,
    "_run_strictcli_schema_dump": None,
    "_run_selfdoc_gen": None,
    "_run_selfdoc_check": None,
    "_run_selfdoc_post_generate": None,
    "generate_changelog": "# Changelog\n\n## 0.1.1\n\n- test\n",
    "resolve_release_targets": [],
    "_run_release_mutating": None,
    "acquire_lock": None,
    "release_lock": None,
}

_MODULE = "rlsbl.commands.release"


def _apply_base_patches(extra_patches=None):
    """Return a list of patch context managers for the base + extra patches.

    Usage::

        with _apply_base_patches({"run": my_side_effect}) as mocks:
            _run_cmd_inner(config, flags, ctx=ctx)
            mocks["run"].assert_called(...)
    """
    # This is used as a helper inside each test; we build the real
    # contextmanager below.
    pass


class _PatchContext:
    """Context manager that applies all base patches plus extras."""

    def __init__(self, extras=None):
        self._extras = extras or {}
        self._stack = []
        self.mocks = {}

    def __enter__(self):
        import contextlib
        for name, return_value in _BASE_PATCHES.items():
            if name in self._extras:
                continue  # caller will handle this one
            p = patch(f"{_MODULE}.{name}", return_value=return_value)
            self.mocks[name] = p.start()
            self._stack.append(p)

        for name, value in self._extras.items():
            if callable(value) and not isinstance(value, MagicMock):
                p = patch(f"{_MODULE}.{name}", side_effect=value)
            else:
                p = patch(f"{_MODULE}.{name}", return_value=value)
            self.mocks[name] = p.start()
            self._stack.append(p)

        return self.mocks

    def __exit__(self, *exc):
        for p in reversed(self._stack):
            p.stop()
        return False


# ---------------------------------------------------------------------------
# 1. Source-level ordering: selfdoc commit block appears after selfdoc ops
#    and before the releasable/standalone hook divergence.
# ---------------------------------------------------------------------------


class TestSelfdocCommitOrdering:
    """Verify that the selfdoc commit block is positioned correctly."""

    def test_commit_after_selfdoc_post_generate(self):
        """The commit_files call for selfdoc must appear after _run_selfdoc_post_generate."""
        from rlsbl.commands.release import _run_cmd_inner
        source = inspect.getsource(_run_cmd_inner)
        post_gen_pos = source.index("_run_selfdoc_post_generate(")
        commit_pos = source.index('"selfdoc: regenerate"')
        assert post_gen_pos < commit_pos, (
            "selfdoc commit must appear after _run_selfdoc_post_generate"
        )

    def test_commit_before_releasable_hook_branch(self):
        """The selfdoc commit must appear before the releasable vs standalone divergence."""
        from rlsbl.commands.release import _run_cmd_inner
        source = inspect.getsource(_run_cmd_inner)
        commit_pos = source.index('"selfdoc: regenerate"')
        # The divergence point is `if _use_releasable_hooks:` after selfdoc ops
        # Find the SECOND occurrence (the one after selfdoc)
        first_use = source.index("if _use_releasable_hooks:")
        second_use = source.index("if _use_releasable_hooks:", first_use + 1)
        assert commit_pos < second_use, (
            "selfdoc commit must appear before the post-selfdoc releasable hook check"
        )

    def test_commit_before_post_hook_snapshot(self):
        """The selfdoc commit must appear before the post_hook_dirty snapshot."""
        from rlsbl.commands.release import _run_cmd_inner
        source = inspect.getsource(_run_cmd_inner)
        commit_pos = source.index('"selfdoc: regenerate"')
        post_hook_pos = source.index("post_hook_dirty = parse_porcelain_paths")
        assert commit_pos < post_hook_pos, (
            "selfdoc commit must appear before post_hook_dirty snapshot"
        )

    def test_commit_uses_autogenerated_true(self):
        """The selfdoc commit must use autogenerated=True."""
        from rlsbl.commands.release import _run_cmd_inner
        source = inspect.getsource(_run_cmd_inner)
        # Find the commit_files call near "selfdoc: regenerate"
        selfdoc_commit_start = source.index('"selfdoc: regenerate"')
        # Look for autogenerated=True in the same commit_files call
        # (within a reasonable range)
        region = source[selfdoc_commit_start:selfdoc_commit_start + 200]
        assert "autogenerated=True" in region, (
            "selfdoc commit_files call must use autogenerated=True"
        )


# ---------------------------------------------------------------------------
# 2. Behavioral tests: selfdoc-generated files are committed
# ---------------------------------------------------------------------------


class TestSelfdocFilesCommitted:
    """Selfdoc-generated files are committed after selfdoc operations."""

    def test_selfdoc_generated_files_committed_standalone(self, tmp_path):
        """In standalone mode, files dirtied by selfdoc are committed."""
        from rlsbl.commands.release import _run_cmd_inner

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        # Track which git-status calls we've seen.
        # Call order: pre_hook, pre_selfdoc, post_selfdoc, post_hook
        git_status_call_count = [0]

        def fake_run(tool, args, **kwargs):
            if tool == "git" and args == ["status", "--porcelain"]:
                git_status_call_count[0] += 1
                n = git_status_call_count[0]
                if n == 1:
                    # pre_hook_dirty: tree is clean
                    return ""
                elif n == 2:
                    # pre_selfdoc: still clean (pre-checks didn't dirty anything)
                    return ""
                elif n == 3:
                    # post_selfdoc: selfdoc dirtied README.md and docs/index.md
                    return " M README.md\n?? docs/index.md\n"
                else:
                    # post_hook: after commit, tree is clean again
                    return ""
            return ""

        commit_calls = []

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            commit_calls.append({
                "message": message,
                "files": files,
                "autogenerated": autogenerated,
            })
            return True

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        with _PatchContext({"run": fake_run, "commit_files": fake_commit_files}) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                _run_cmd_inner(config, {}, ctx=ctx)

        assert len(commit_calls) == 1
        assert commit_calls[0]["message"] == "selfdoc: regenerate"
        assert commit_calls[0]["autogenerated"] is True
        # Files should be sorted
        assert commit_calls[0]["files"] == ["README.md", "docs/index.md"]

    def test_selfdoc_generated_files_committed_releasable(self, tmp_path):
        """In releasable mode, files dirtied by selfdoc are committed."""
        from rlsbl.commands.release import _run_cmd_inner

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        # Call order: pre_hook, pre_selfdoc, post_selfdoc, post_hook
        git_status_call_count = [0]

        def fake_run(tool, args, **kwargs):
            if tool == "git" and args == ["status", "--porcelain"]:
                git_status_call_count[0] += 1
                n = git_status_call_count[0]
                if n <= 2:
                    # pre_hook and pre_selfdoc: clean
                    return ""
                elif n == 3:
                    # post_selfdoc: CLAUDE.md dirtied
                    return " M CLAUDE.md\n"
                else:
                    # post_hook: clean after commit
                    return ""
            return ""

        commit_calls = []

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            commit_calls.append({
                "message": message,
                "files": files,
                "autogenerated": autogenerated,
            })
            return True

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        # Override resolve_monorepo_context for releasable path
        releasable_overrides = {
            "run": fake_run,
            "commit_files": fake_commit_files,
            "resolve_monorepo_context": (None, None, False, False, "my-releasable"),
        }

        # The releasable path imports load_releasables, load_workspace,
        # members_of from rlsbl.workspace at function scope.  Mock at the
        # source module so the local import picks them up.
        fake_proj = {"name": "pkg-a", "path": "pkg-a"}
        fake_releasable = MagicMock()
        fake_releasable.name = "my-releasable"
        fake_releasable.tag_format = None

        with _PatchContext(releasable_overrides) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                with patch("rlsbl.workspace.load_releasables", return_value=[fake_releasable]):
                    with patch("rlsbl.workspace.members_of", return_value=[fake_proj]):
                        with patch("rlsbl.workspace.load_workspace", return_value=[]):
                            with patch(f"{_MODULE}.run_releasable_hooks"):
                                with patch(f"{_MODULE}.is_releasable_hook_customized", return_value=True):
                                    _run_cmd_inner(config, {}, ctx=ctx)

        assert len(commit_calls) == 1
        assert commit_calls[0]["message"] == "selfdoc: regenerate"
        assert commit_calls[0]["files"] == ["CLAUDE.md"]


# ---------------------------------------------------------------------------
# 3. No commit when selfdoc changes nothing
# ---------------------------------------------------------------------------


class TestSelfdocNoopSkipsCommit:
    """When selfdoc produces no new dirty files, no commit is created."""

    def test_no_commit_when_selfdoc_changes_nothing(self, tmp_path):
        """If the tree is unchanged after selfdoc ops, commit_files is not called for selfdoc."""
        from rlsbl.commands.release import _run_cmd_inner

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        # All git status calls return empty (clean tree throughout)
        def fake_run(tool, args, **kwargs):
            return ""

        commit_calls = []

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            commit_calls.append(message)
            return True

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        with _PatchContext({"run": fake_run, "commit_files": fake_commit_files}) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                _run_cmd_inner(config, {}, ctx=ctx)

        # No selfdoc commit should have been made (commit_files not called at all
        # from the pre-mutating path; the mutating path is fully mocked out).
        selfdoc_commits = [m for m in commit_calls if "selfdoc" in m]
        assert selfdoc_commits == []


# ---------------------------------------------------------------------------
# 4. Pre-existing dirty files are NOT committed by selfdoc logic
# ---------------------------------------------------------------------------


class TestSelfdocIgnoresPreExistingDirty:
    """Files dirty before selfdoc ops are NOT included in the selfdoc commit."""

    def test_pre_existing_dirty_excluded(self, tmp_path):
        """Only files that are NEW after selfdoc ops are committed."""
        from rlsbl.commands.release import _run_cmd_inner

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        # Call order: pre_hook, pre_selfdoc, post_selfdoc, post_hook
        git_status_call_count = [0]

        def fake_run(tool, args, **kwargs):
            if tool == "git" and args == ["status", "--porcelain"]:
                git_status_call_count[0] += 1
                n = git_status_call_count[0]
                if n <= 2:
                    # pre_hook and pre_selfdoc: one file already dirty
                    return " M already-dirty.txt\n"
                elif n == 3:
                    # post_selfdoc: pre-existing file + one new selfdoc file
                    return " M already-dirty.txt\n M README.md\n"
                else:
                    # post_hook: same as pre-hook (selfdoc file committed)
                    return " M already-dirty.txt\n"
            return ""

        commit_calls = []

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            commit_calls.append({"files": files})
            return True

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        with _PatchContext({"run": fake_run, "commit_files": fake_commit_files}) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                _run_cmd_inner(config, {}, ctx=ctx)

        assert len(commit_calls) == 1
        # Only README.md should be committed, not already-dirty.txt
        assert commit_calls[0]["files"] == ["README.md"]


# ---------------------------------------------------------------------------
# 5. hook_generated does NOT include already-committed selfdoc files
# ---------------------------------------------------------------------------


class TestHookGeneratedExcludesSelfdocFiles:
    """After selfdoc files are committed, they don't appear in hook_generated."""

    def test_committed_selfdoc_files_absent_from_hook_generated(self, tmp_path):
        """hook_generated = post_hook_dirty - pre_hook_dirty should NOT
        include selfdoc files that were committed before the post-hook snapshot."""
        from rlsbl.commands.release import _run_cmd_inner

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        # Call order: pre_hook, pre_selfdoc, post_selfdoc, post_hook
        git_status_call_count = [0]

        def fake_run(tool, args, **kwargs):
            if tool == "git" and args == ["status", "--porcelain"]:
                git_status_call_count[0] += 1
                n = git_status_call_count[0]
                if n <= 2:
                    return ""  # pre_hook and pre_selfdoc: clean
                elif n == 3:
                    return " M README.md\n"  # post_selfdoc: README dirtied
                else:
                    # post_hook: README.md was committed, but hooks added hook-file.txt
                    return " M hook-file.txt\n"
            return ""

        captured_state = {}

        def fake_mutating(state):
            captured_state["hook_generated"] = state.hook_generated

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            return True

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        with _PatchContext({
            "run": fake_run,
            "commit_files": fake_commit_files,
            "_run_release_mutating": fake_mutating,
        }) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                _run_cmd_inner(config, {}, ctx=ctx)

        # hook_generated should contain ONLY hook-file.txt, NOT README.md
        assert captured_state["hook_generated"] == {"hook-file.txt"}


