# ---------------------------------------------------------------------------
# 7. Dry run skips selfdoc commit
# ---------------------------------------------------------------------------


class TestSelfdocCommitDryRun:
    """In dry-run mode, the selfdoc commit is skipped."""

    def test_dry_run_skips_selfdoc_commit(self, tmp_path):
        """With --dry-run, commit_files is not called for selfdoc files."""
        from rlsbl.commands.release import _run_cmd_inner

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        commit_calls = []

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            commit_calls.append(message)
            return True

        extras = {
            "run": lambda *a, **k: "",
            "commit_files": fake_commit_files,
            "print_dry_run_summary": MagicMock(),
        }

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        with _PatchContext(extras) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                _run_cmd_inner(config, {"dry-run": True}, ctx=ctx)

        selfdoc_commits = [m for m in commit_calls if "selfdoc" in m]
        assert selfdoc_commits == []


# ---------------------------------------------------------------------------
# 8. Simulated release failure after selfdoc gen leaves tree clean
# ---------------------------------------------------------------------------


class TestReleaseFailureAfterSelfdoc:
    """A release failure after selfdoc gen leaves the tree clean of selfdoc artifacts."""

    def test_failure_after_selfdoc_tree_clean(self, tmp_path):
        """When _run_release_mutating raises, selfdoc files have already been committed."""
        from rlsbl.commands.release import _run_cmd_inner
        from rlsbl.commands.release.execute import ReleaseAbortError

        ctx = _make_release_context(tmp_path)
        config = _make_release_config()

        # Call order: pre_hook, pre_selfdoc, post_selfdoc, post_hook
        git_status_call_count = [0]

        def fake_run(tool, args, **kwargs):
            if tool == "git" and args == ["status", "--porcelain"]:
                git_status_call_count[0] += 1
                # post_selfdoc (call 3) returns dirty files
                if git_status_call_count[0] == 3:
                    return " M README.md\n M docs/api.md\n"
                return ""
            return ""

        committed_files = []

        def fake_commit_files(message, files, autogenerated=True, **kwargs):
            committed_files.extend(files)
            return True

        def fake_mutating(state):
            raise ReleaseAbortError("simulated failure")

        from rlsbl.commands.release.validate import parse_porcelain_paths as real_parse

        with _PatchContext({
            "run": fake_run,
            "commit_files": fake_commit_files,
            "_run_release_mutating": fake_mutating,
        }) as mocks:
            with patch(f"{_MODULE}.parse_porcelain_paths", side_effect=real_parse):
                with pytest.raises(SystemExit):
                    _run_cmd_inner(config, {}, ctx=ctx)

        # The selfdoc files were committed BEFORE the failure
        assert "README.md" in committed_files
        assert "docs/api.md" in committed_files
